    await assert.rejects(
      new EmberStore(dir).save(
        { version: 1, repoRoot: dir, embedderKind: "x", dim: 1, chunkCount: 0, fileCount: 0, createdAt: "", updatedAt: "" },
        [], [], new (await import("../src/core/hnsw.js")).HnswIndex(1),
      ),
