  if (!NAME.test(owner) || !NAME.test(repo)) throw new Error(`invalid owner or repo name: ${owner}/${repo}`);
  return { owner, repo, ref, cloneUrl: `https://github.com/${owner}/${repo}.git`, label: ref ? `${owner}/${repo}@${ref}` : `${owner}/${repo}` };
