  while ((i = buf.indexOf("\n")) >= 0) {

    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    if (line.startsWith("EMBER_RESULT_JSON:")) { try { result = JSON.parse(line.slice(18)); } catch { /* ignore */ } }
    else if (line.trim()) onLine(line);
